# In reality, we can just use a real FastAPI app and check how it handles it.

class MyCallable:
    async def __call__(self):
        return "hello"

app = FastAPI()

@app.get("/")
async def root(dep = Depends(MyCallable)):
    return {"dep": dep}

client = TestClient(app)

def test_repro():
    # If MyCallable is used as a dependency, FastAPI should treat it as a regular callable
    # that returns an instance of MyCallable.
    # But the issue is that it's mistakenly treated as a coroutine callable.

    # Let's see what happens when we use it.
    # If it's treated as a coroutine, FastAPI will await it.
    # If it's treated as a regular callable, FastAPI will call it and get an instance.

    # The problem is in the detection logic.
    # Let's manually test the detection logic.

    # We need to create a Dependant object.
    # Dependant is created in fastapi.routing.get_dependant

    from fastapi.routing import get_dependant

    # We need a call object.
    call = MyCallable

    # We can't easily call get_dependant without a lot of setup.
    # Let's just use the logic from models.py.

    # Mocking Dependant for the sake of testing the properties.
    class MockDependant:
        def __init__(self, call):
            self.call = call

        @property
        def is_gen_callable(self):
            # Copy from models.py
            if self.call is None:
                return False
            if inspect.isgeneratorfunction(_impartial(self.call)) or inspect.isgeneratorfunction(_unwrapped_call(self.call)):
                return True
            dunder_call = getattr(_impartial(self.call), "__call__", None)
            if dunder_call is None:
                return False
            if inspect.isgeneratorfunction(_impartial(dunder_call)) or inspect.isgeneratorfunction(_unwrapped_call(dunder_call)):
                return True
            dunder_unwrapped_call = getattr(_unwrapped_call(self.call), "__call__", None)
            if dunder_unwrapped_call is None:
                return False
            if inspect.isgeneratorfunction(_impartial(dunder_unwrapped_call)) or inspect.isgeneratorfunction(_unwrapped_call(dunder_unwrapped_call)):
                return True
            return False

        @property
        def is_async_gen_callable(self):
            # Copy from models.py
            if self.call is None:
                return False
            if inspect.isasyncgenfunction(_impartial(self.call)) or inspect.isasyncgenfunction(_unwrapped_call(self.call)):
                return True
            dunder_call = getattr(_impartial(self.call), "__call__", None)
            if dunder_call is None:
                return False
            if inspect.isasyncgenfunction(_impartial(dunder_call)) or inspect.isasyncgenfunction(_unwrapped_call(dunder_call)):
                return True
            dunder_unwrapped_call = getattr(_unwrapped_call(self.call), "__call__", None)
            if dunder_unwrapped_call is None:
                return False
            if inspect.isasyncgenfunction(_impartial(dunder_unwrapped_call)) or inspect.isasyncgenfunction(_unwrapped_call(dunder_unwrapped_call)):
                return True
            return False

        @property
        def is_coroutine_callable(self):
            # Copy from models.py
            from fastapi.dependencies.models import iscoroutinefunction
            if self.call is None:
                return False
            if inspect.isroutine(_impartial(self.call)) and iscoroutinefunction(_impartial(self.call)):
                return True
            if inspect.isroutine(_unwrapped_call(self.call)) and iscoroutinefunction(_unwrapped_call(self.call)):
                return True
            dunder_call = getattr(_impartial(self.call), "__call__", None)
            if dunder_call is None:
                return False
            if iscoroutinefunction(_impartial(dunder_call)) or iscoroutinefunction(_unwrapped_call(dunder_call)):
                return True
            dunder_unwrapped_call = getattr(_unwrapped_call(self.call), "__call__", None)
            if dunder_unwrapped_call is None:
                return False
            if iscoroutinefunction(_impartial(dunder_unwrapped_call)) or iscoroutinefunction(_unwrapped_call(dunder_unwrapped_call)):
                return True
            return False

    dep = MockDependant(MyCallable)
    print(f"is_coroutine_callable: {dep.is_coroutine_callable}")
    print(f"is_async_gen_callable: {dep.is_async_gen_callable}")
    print(f"is_gen_callable: {dep.is_gen_callable}")

